        "code": "def main(url: str):\n\turl = url.strip().rstrip('/')\n\tif url.endswith('.git'):\n\t\turl = url[:-4]\n\tparts = url.split('/')\n\towner = parts[-2]\n\trepo = parts[-1]\n\treturn {\n\t\t\"repo_api_url\": f\"https://api.github.com/repos/{owner}/{repo}\"\n\t}"
